CREATE TABLE IF NOT EXISTS public."products" (\n  "id" text DEFAULT ('p_'::text || ((EXTRACT(epoch FROM now()))::bigint)::text) NOT NULL,\n  "name" text NOT NULL,\n  "slug" text NOT NULL,\n  "description" text DEFAULT ''::text,\n  "price" numeric NOT NULL,\n  "discounted_price" numeric,\n  "old_price" numeric,\n  "category" text NOT NULL,\n  "brand" text,\n  "images" ARRAY DEFAULT '{}'::text[],\n  "in_stock" boolean DEFAULT true,\n  "stock_count" integer DEFAULT 0,\n  "variants" jsonb DEFAULT '[]'::jsonb,\n  "features" ARRAY DEFAULT '{}'::text[],\n  "reviews" jsonb DEFAULT '[]'::jsonb,\n  "is_new" boolean DEFAULT false,\n  "is_bestseller" boolean DEFAULT false,\n  "is_featured" boolean DEFAULT false,\n  "shopier_url" text,\n  "badge_text" text,\n  "badge_color" text,\n  "created_at" timestamp with time zone DEFAULT now(),\n  "cart_discount_percent" integer DEFAULT 0\n);\n\nCREATE TABLE IF NOT EXISTS public."orders" (\n  "id" text DEFAULT ('ORD-'::text || (floor(((100000)::double precision + (random() * (900000)::double precision))))::text) NOT NULL,\n  "user_id" text DEFAULT 'guest'::text,\n  "items" jsonb DEFAULT '[]'::jsonb NOT NULL,\n  "total_amount" numeric NOT NULL,\n  "status" text DEFAULT 'pending'::text,\n  "shipping_address" text DEFAULT ''::text,\n  "customer_email" text,\n  "customer_phone" text,\n  "payment_method" text DEFAULT 'iban'::text,\n  "created_at" timestamp with time zone DEFAULT now(),\n  "is_archived" boolean DEFAULT false,\n  "cargo_company" text,\n  "tracking_number" text,\n  "cancel_reason" text,\n  "used_credit" numeric DEFAULT 0,\n  "is_new" boolean DEFAULT true,\n  "coupon_code" text,\n  "coupon_discount" numeric DEFAULT 0,\n  "cart_discount" numeric DEFAULT 0,\n  "multi_item_discount_amount" numeric DEFAULT 0\n);\n\nCREATE TABLE IF NOT EXISTS public."favorites" (\n  "id" uuid DEFAULT gen_random_uuid() NOT NULL,\n  "user_id" uuid NOT NULL,\n  "product_id" text NOT NULL,\n  "created_at" timestamp with time zone DEFAULT now()\n);\n\nCREATE TABLE IF NOT EXISTS public."user_carts" (\n  "id" uuid DEFAULT gen_random_uuid() NOT NULL,\n  "user_id" uuid NOT NULL,\n  "items" jsonb DEFAULT '[]'::jsonb NOT NULL,\n  "updated_at" timestamp with time zone DEFAULT now()\n);\n\nCREATE TABLE IF NOT EXISTS public."profiles" (\n  "id" uuid NOT NULL,\n  "full_name" text,\n  "email" text,\n  "role" text DEFAULT 'customer'::text,\n  "created_at" timestamp with time zone DEFAULT now(),\n  "credit_balance" numeric DEFAULT 0,\n  "is_banned" boolean DEFAULT false\n);\n\nCREATE TABLE IF NOT EXISTS public."settings" (\n  "id" bigint DEFAULT 1 NOT NULL,\n  "maintenance_mode" boolean DEFAULT false,\n  "maintenance_until" timestamp with time zone,\n  "maintenance_message" text,\n  "updated_at" timestamp with time zone DEFAULT now(),\n  "announcement_mode" boolean DEFAULT false,\n  "announcement_text" text DEFAULT '🔥 300 TL Üzeri Ücretsiz gönderim • 🚚 Hızlı kargo • 🔒 Güvenli alışveriş • 💳 Taksitli ödeme imkanı'::text,\n  "announcement_color" text DEFAULT '#d4af37'::text,\n  "announcement_bg_color" text DEFAULT '#111111'::text,\n  "topbar_mode" boolean DEFAULT false,\n  "topbar_text" text DEFAULT '🔥 300 TL Üzeri Ücretsiz gönderim • 🚚 Hızlı kargo • 🔒 Güvenli alışveriş • 💳 Taksitli ödeme imkanı'::text,\n  "topbar_color" text DEFAULT '#ffffff'::text,\n  "topbar_bg_color" text DEFAULT '#d4af37'::text,\n  "topbar_speed" integer DEFAULT 2,\n  "topbar_height" integer DEFAULT 40,\n  "global_discount_percent" integer DEFAULT 0,\n  "newest_settings" jsonb DEFAULT '{"limit": 8, "title": "En Yeni Ürünler", "layout": "grid", "enabled": true}'::jsonb,\n  "popup_settings" jsonb DEFAULT '{}'::jsonb,\n  "multi_item_discounts" jsonb DEFAULT '[]'::jsonb,\n  "coupon_popup_settings" jsonb DEFAULT '{}'::jsonb\n);\n\nCREATE TABLE IF NOT EXISTS public."newsletter_subscribers" (\n  "id" uuid DEFAULT gen_random_uuid() NOT NULL,\n  "email" text NOT NULL,\n  "created_at" timestamp with time zone DEFAULT now()\n);\n\nCREATE TABLE IF NOT EXISTS public."coupons" (\n  "id" uuid DEFAULT gen_random_uuid() NOT NULL,\n  "code" text NOT NULL,\n  "discount_type" text NOT NULL,\n  "discount_value" numeric NOT NULL,\n  "min_amount" numeric DEFAULT 0,\n  "is_active" boolean DEFAULT true,\n  "created_at" timestamp with time zone DEFAULT now(),\n  "usage_limit" integer,\n  "used_count" integer DEFAULT 0\n);\n\nCREATE TABLE IF NOT EXISTS public."showcases" (\n  "id" bigint NOT NULL,\n  "title" text NOT NULL,\n  "category" text,\n  "brand" text,\n  "limit_count" integer DEFAULT 4,\n  "layout" text DEFAULT 'grid'::text,\n  "display_order" integer DEFAULT 0,\n  "created_at" timestamp with time zone DEFAULT now()\n);\n\nCREATE TABLE IF NOT EXISTS public."contact_messages" (\n  "id" uuid DEFAULT gen_random_uuid() NOT NULL,\n  "name" text,\n  "email" text NOT NULL,\n  "phone" text,\n  "message" text NOT NULL,\n  "created_at" timestamp with time zone DEFAULT now(),\n  "is_read" boolean DEFAULT false\n);\n\nCREATE TABLE IF NOT EXISTS public."promo_blocks" (\n  "id" text NOT NULL,\n  "enabled" boolean DEFAULT true,\n  "title" text,\n  "description" text,\n  "button_text" text,\n  "button_link" text,\n  "image" text,\n  "image_position" text DEFAULT 'right'::text,\n  "display_order" integer DEFAULT 0,\n  "created_at" timestamp with time zone DEFAULT timezone('utc'::text, now())\n);\n\nCREATE TABLE IF NOT EXISTS public."slider_images" (\n  "id" uuid DEFAULT uuid_generate_v4() NOT NULL,\n  "image_url" text NOT NULL,\n  "title" text,\n  "link" text,\n  "display_order" integer DEFAULT 0,\n  "created_at" timestamp with time zone DEFAULT timezone('utc'::text, now())\n);\n\n